/**
 * The built client applies the page-POST fallback's recorded answers (#4108).
 *
 * `fixtures/http_fallback_replay_4108.json` is generated by
 * `python/djust/tests/test_http_fallback_differential_4108.py` from the real
 * server: for each scenario the page GET document, the answer to every
 * fallback POST of an event sequence, and the DOM the browser must end with
 * (the WebSocket session's final render of the same sequence, where the two
 * transports agree). Each answer goes through the real `handleEvent` fallback
 * path of the built `client.js`, starting from the GET document parsed with
 * its whitespace, and the resulting DOM is compared node by node.
 */
import {describe, it, expect} from 'vitest';
import {readFileSync} from 'node:fs';
import {loadPage, domDifference, eventTarget} from './_http_fallback_replay.js';

const fixture = JSON.parse(
    readFileSync('./tests/js/fixtures/http_fallback_replay_4108.json', 'utf8'));

describe('page-POST fallback replay', () => {
    for (const [name, scenario] of Object.entries(fixture.scenarios)) {
        it(`${name}: the client ends with the expected DOM`, async () => {
            const page = loadPage(scenario.get, scenario.url);
            try {
                const {win} = page;
                for (let i = 0; i < scenario.events.length; i++) {
                    const [event, params] = scenario.events[i];
                    const request = await page.send(event, params, scenario.answers[i],
                        eventTarget(win, event, params));
                    // The client echoes the digest the page (then each answer) carried.
                    expect(request.digest, `${name} step ${i + 1}: echoed digest`)
                        .toBe(scenario.sent_digests[i]);
                    expect(scenario.kinds[i]).toBe(
                        'patches' in scenario.answers[i] ? 'patches' : 'html');
                }
                for (const mask of fixture.masks) {
                    for (const el of win.document.querySelectorAll(mask.selector)) {
                        el.textContent = mask.text;
                    }
                }
                expect(domDifference(win, scenario.expected_dom), name).toBe(null);
                expect(page.reloads(), `${name}: no page reload`).toBe(0);
                expect(page.problems(), `${name}: no client warning or error`).toEqual([]);
            } finally { page.close(); }
        });
    }

    it('covers every transport outcome the server test pins', () => {
        const kinds = new Set(Object.values(fixture.scenarios).flatMap(s => s.kinds));
        expect(kinds.has('html')).toBe(true);
    });
});
